import json
def objects(g, bg):
    seen=set(); objs=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; stack=[(i,j)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
                            stack.append((ny,nx))
                objs.append((col,comp))
    return objs
def interior_cells(g, bg):
    H,W=len(g),len(g[0])
    # flood bg from border; unreached bg = enclosed
    from collections import deque
    out=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==bg: out.add((i,j))
    seen=set()
    dq=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==bg and (i,j) not in seen: seen.add((i,j)); dq.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==bg and (i,j) not in seen: seen.add((i,j)); dq.append((i,j))
    while dq:
        y,x=dq.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and g[ny][nx]==bg and (ny,nx) not in seen:
                seen.add((ny,nx)); dq.append((ny,nx))
    return out-seen
def transform(g):
    bg=g[0][0]
    objs=objects(g,bg)
    small=min(objs,key=lambda o:len(o[1]))[0]
    g=[row[:] for row in g]
    for i,j in interior_cells(g,bg): g[i][j]=small
    return g
